/// <summary>
/// modified function for formDataSource field MarkupCategory
/// </summary>
public void modified()
{
    next modified();

    MarkupTrans markupTransLoc = this.dataSource().cursor();

    if(markupTransLoc.MarkupCategory == MarkupCategory::AVAMTZ)
    {
        element.avaEnableCalcQty();
    }
}
